create extension if not exists pgcrypto;
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = timezone('utc'::text, now()); return new; end; $$;
create table if not exists public.profiles ( id uuid primary key references auth.users(id) on delete cascade, full_name text, role text not null default 'reader' check (role in ('reader', 'author', 'affiliate', 'admin')), created_at timestamptz not null default timezone('utc'::text, now()), updated_at timestamptz not null default timezone('utc'::text, now()) );
create table if not exists public.authors ( id uuid primary key default gen_random_uuid(), profile_id uuid references public.profiles(id) on delete set null, name text not null, slug text not null unique, headline text, bio text, avatar_url text, socials jsonb not null default '{}'::jsonb, created_at timestamptz not null default timezone('utc'::text, now()), updated_at timestamptz not null default timezone('utc'::text, now()) );
create table if not exists public.books ( id uuid primary key default gen_random_uuid(), author_id uuid not null references public.authors(id) on delete cascade, slug text not null unique, title text not null, subtitle text, short_description text not null, description text not null, excerpt text, price numeric(10,2) not null default 0, compare_at_price numeric(10,2), cover_url text, rating numeric(3,2) not null default 0, review_count integer not null default 0, page_count integer not null default 0, language text not null default 'Español', isbn text, formats text[] not null default '{print,ebook,reader}', categories text[] not null default '{}', badge text, is_featured boolean not null default false, status text not null default 'draft' check (status in ('draft', 'published', 'archived')), kindle_url text, publication_date date, created_at timestamptz not null default timezone('utc'::text, now()), updated_at timestamptz not null default timezone('utc'::text, now()) );
create table if not exists public.author_applications ( id uuid primary key default gen_random_uuid(), full_name text not null, email text not null, phone text, manuscript_title text not null, status text not null default 'new' check (status in ('new', 'reviewing', 'approved', 'rejected')), notes text, created_at timestamptz not null default timezone('utc'::text, now()) );
create table if not exists public.affiliate_applications ( id uuid primary key default gen_random_uuid(), full_name text not null, email text not null, channels text, audience text, status text not null default 'new' check (status in ('new', 'reviewing', 'approved', 'rejected')), created_at timestamptz not null default timezone('utc'::text, now()) );
create table if not exists public.orders ( id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id) on delete set null, email text not null, status text not null default 'pending' check (status in ('pending', 'paid', 'cancelled', 'fulfilled')), subtotal numeric(10,2) not null default 0, total numeric(10,2) not null default 0, currency text not null default 'USD', payment_provider text, payment_status text not null default 'pending' check (payment_status in ('pending', 'authorized', 'paid', 'failed', 'refunded')), shipping_address jsonb not null default '{}'::jsonb, created_at timestamptz not null default timezone('utc'::text, now()) );
create table if not exists public.order_items ( id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, book_id uuid not null references public.books(id) on delete cascade, format text not null, quantity integer not null default 1, unit_price numeric(10,2) not null default 0, created_at timestamptz not null default timezone('utc'::text, now()) );
create trigger set_profiles_updated_at before update on public.profiles for each row execute procedure public.set_updated_at();
create trigger set_authors_updated_at before update on public.authors for each row execute procedure public.set_updated_at();
create trigger set_books_updated_at before update on public.books for each row execute procedure public.set_updated_at();
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id, full_name, role) values (new.id, coalesce(new.raw_user_meta_data ->> 'full_name', split_part(new.email, '@', 1)), 'reader') on conflict (id) do nothing; return new; end; $$;
create or replace trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; alter table public.authors enable row level security; alter table public.books enable row level security; alter table public.author_applications enable row level security; alter table public.affiliate_applications enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security;
create policy "public read authors" on public.authors for select using (true);
create policy "public read published books" on public.books for select using (status = 'published');
create policy "anon insert author applications" on public.author_applications for insert to anon, authenticated with check (true);
create policy "anon insert affiliate applications" on public.affiliate_applications for insert to anon, authenticated with check (true);
create policy "anon create orders" on public.orders for insert to anon, authenticated with check (true);
create policy "anon create order items" on public.order_items for insert to anon, authenticated with check (true);
create policy "users read own profile" on public.profiles for select to authenticated using (auth.uid() = id);
create policy "users update own profile" on public.profiles for update to authenticated using (auth.uid() = id) with check (auth.uid() = id);
